 cat=json.loads((ROOT/'course_catalog.json').read_text()); by={x['id']:x for x in cat}
 for lid,title,code,summary,example,task,checks in DATA:
  item=by.get(lid,{'id':lid,'quarter':int(lid[1]),'order':int(lid[-2:]),'kind':'lesson','resources':[]})
  item.update(title=title,objective=code,summary=summary+'\n\nМысал:\n'+example+'\n\nОйын алдындағы дайындық: '+task)
  by[lid]=item
 cat=sorted(by.values(),key=lambda x:(x['quarter'],x['order']))
 (ROOT/'course_catalog.json').write_text(json.dumps(cat,ensure_ascii=False,indent=2))
 payload={lid:{'summary':summary+'\n\n'+example,'example':example,'task':task,'questions':[q(str(i+1),prompt,options,correct,'Түсіндірмені және мысалды салыстыр.') for i,(prompt,options,correct) in enumerate(checks)]} for lid,title,code,summary,example,task,checks in DATA}
 (ROOT/'materials/extended-content.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2))
 print('Added/updated',len(DATA),'lessons; total',len(cat))
